int offset = 0;
while (offset < buffer.Length)
{
    int n = await socket.ReceiveAsync(buffer.AsMemory(offset), SocketFlags.None, ct);
    if (n == 0)
    {
        if (offset == 0 && allowCleanEof) return false;
        throw new EndOfStreamException($"EOF at {offset}/{buffer.Length}");
    }
    offset += n;
}
return true;
